H,W=13,23
g=[[2]*W for _ in range(H)]
# line seed pair, walk backward from first and onward
for color,r,c,dc in [(8,2,14,1),(7,2,17,-1),(5,4,15,-1),(3,4,16,1)]:
    rr,cc=r,c
    while 0<=rr-1<H and 0<=cc-dc<W:
        rr-=1;cc-=dc
    while 0<=rr<H and 0<=cc<W:
        g[rr][cc]=color;rr+=1;cc+=dc
print(g)
